<script>
(function() {
  'use strict';

  // ── Mobile menu toggle ──
  const hamburger = document.getElementById('hamburger');
  const mobileNav = document.getElementById('mobile-nav');
  let menuOpen = false;

  function openMenu() {
    menuOpen = true;
    mobileNav.classList.add('open');
    hamburger.classList.add('active');
    hamburger.setAttribute('aria-expanded', 'true');
    document.body.style.overflow = 'hidden';
    hamburger.focus();
  }

  function closeMenu() {
    menuOpen = false;
    mobileNav.classList.remove('open');
    hamburger.classList.remove('active');
    hamburger.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
  }

  hamburger.addEventListener('click', function() {
    menuOpen ? closeMenu() : openMenu();
  });

  // Close mobile nav when a link is clicked
  mobileNav.querySelectorAll('a').forEach(function(link) {
    link.addEventListener('click', closeMenu);
  });

  // Close on Escape
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && menuOpen) closeMenu();
  });

  // ── Search autocomplete ──
  var searchInput = document.getElementById('search-query');
  var autocompleteList = document.getElementById('autocomplete-list');
  var searchForm = document.getElementById('search-form');

  var suggestions = [
    { label: 'Dentist', type: 'Specialty', icon: '🦷' },
    { label: 'Primary Care', type: 'Specialty', icon: '🏥' },
    { label: 'Dermatologist', type: 'Specialty', icon: '🔬' },
    { label: 'Psychiatrist', type: 'Specialty', icon: '🧠' },
    { label: 'Eye Doctor', type: 'Specialty', icon: '👁' },
    { label: 'Orthopedic Surgeon', type: 'Specialty', icon: '🦴' },
    { label: 'Cardiologist', type: 'Specialty', icon: '❤️' },
    { label: 'Pediatrician', type: 'Specialty', icon: '👶' },
    { label: 'Back pain', type: 'Condition', icon: '🔍' },
    { label: 'Annual physical', type: 'Visit type', icon: '📋' },
    { label: 'Teeth cleaning', type: 'Procedure', icon: '✨' },
    { label: 'Flu shot', type: 'Procedure', icon: '💉' }
  ];

  var activeIndex = -1;

  function showAutocomplete(query) {
    if (!query || query.trim().length === 0) {
      hideAutocomplete();
      return;
    }
    var q = query.toLowerCase().trim();
    var matches = suggestions.filter(function(s) {
      return s.label.toLowerCase().includes(q);
    });

    if (matches.length === 0) {
      autocompleteList.innerHTML = '<div style="padding:12px 16px;color:#6B7280;font-size:14px;">No suggestions found</div>';
      autocompleteList.classList.add('active');
      searchInput.setAttribute('aria-expanded', 'true');
      activeIndex = -1;
      return;
    }

    var html = '';
    matches.forEach(function(item, i) {
      var label = item.label;
      var idx = label.toLowerCase().indexOf(q);
      var highlighted = '';
      if (idx >= 0) {
        highlighted = label.substring(0, idx) + '<strong>' + label.substring(idx, idx + q.length) + '</strong>' + label.substring(idx + q.length);
      } else {
        highlighted = label;
      }
      html += '<button type="button" class="autocomplete-item" role="option" data-index="' + i + '" data-value="' + label + '">' +
        '<span class="ac-icon">' + item.icon + '</span>' +
        '<span class="ac-label">' + highlighted + '</span>' +
        '<span class="ac-type">' + item.type + '</span>' +
        '</button>';
    });
    autocompleteList.innerHTML = html;
    autocompleteList.classList.add('active');
    searchInput.setAttribute('aria-expanded', 'true');
    activeIndex = -1;
  }

  function hideAutocomplete() {
    autocompleteList.classList.remove('active');
    searchInput.setAttribute('aria-expanded', 'false');
    activeIndex = -1;
  }

  searchInput.addEventListener('input', function() {
    showAutocomplete(this.value);
  });

  searchInput.addEventListener('focus', function() {
    if (this.value.trim().length > 0) showAutocomplete(this.value);
  });

  searchInput.addEventListener('keydown', function(e) {
    var items = autocompleteList.querySelectorAll('[role="option"]');
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      activeIndex = Math.min(activeIndex + 1, items.length - 1);
      highlightItem(items, activeIndex);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      activeIndex = Math.max(activeIndex - 1, -1);
      highlightItem(items, activeIndex);
    } else if (e.key === 'Enter') {
      if (activeIndex >= 0 && items[activeIndex]) {
        e.preventDefault();
        items[activeIndex].click();
      }
    } else if (e.key === 'Escape') {
      hideAutocomplete();
    }
  });

  function highlightItem(items, index) {
    items.forEach(function(item, i) {
      item.classList.toggle('highlighted', i === index);
      if (i === index) item.focus();
    });
  }

  // Click handler on autocomplete dropdown
  autocompleteList.addEventListener('click', function(e) {
    var item = e.target.closest('[data-value]');
    if (item) {
      searchInput.value = item.getAttribute('data-value');
      hideAutocomplete();
      searchInput.focus();
    }
  });

  // Click outside closes autocomplete
  document.addEventListener('click', function(e) {
    if (!searchInput.contains(e.target) && !autocompleteList.contains(e.target)) {
      hideAutocomplete();
    }
  });

